"""Регрессионные E2E-кейсы, снятые с исправленных известных пробелов."""

from __future__ import annotations

import pytest

from ru_normalizr import NormalizeOptions, normalize


@pytest.mark.parametrize(
    ("source", "expected"),
    [
        pytest.param(
            "Восстановили два гос. пути сообщения.",
            "Восстановили два государственных пути сообщения.",
            id="contextual_adjective_abbreviation",
        ),
        pytest.param(
            "Построили ж.-д. вокзал нового типа.",
            "Построили железнодорожный вокзал нового типа.",
            id="hyphen_joined_dotted_abbreviation",
        ),
        pytest.param(
            "Развиваем с.-х. производство региона.",
            "Развиваем сельскохозяйственное производство региона.",
            id="hyphen_joined_adjective_abbreviation",
        ),
        pytest.param(
            r"Резервная копия лежит в C:\tmp\5MB\s, откройте её вручную.",
            r"Резервная копия лежит в C:\tmp\5MB\s, откройте её вручную.",
            id="windows_path",
        ),
        pytest.param(
            "Для смеси отмерили 5/7 м ленты и добавили краситель.",
            "Для смеси отмерили пять седьмых метра ленты и добавили краситель.",
            id="fraction_with_unit",
        ),
        pytest.param(
            "Ускорение достигло 2 м/с² перед остановкой установки.",
            "Ускорение достигло двух метров в секунду в квадрате перед остановкой установки.",
            id="squared_denominator_unit",
        ),
    ],
)
def test_standalone_known_gap_fixes(source: str, expected: str) -> None:
    assert normalize(source) == expected


def test_social_media_handle_uses_marker_words_and_the_existing_latinization_contract() -> None:
    source = "Напишите пользователю @support_team и укажите номер заявки № 42."
    options = NormalizeOptions.tts(latinization_backend="dictionary")
    assert normalize(source, options) == (
        "Напишите пользователю собака сапорт подчёркивание тим и укажите номер заявки "
        "номер сорок два."
    )


